import { defineChapterTopic, type ChapterAuthorSpec } from '../chapter-package-engine';
import type { EducationTopic } from '../education-types';
import type { VERIFIED_SOURCES } from '../verified-sources';

const MICRO_GAP = {
  status: 'asset_required' as const,
  summary:
    'Organism morphology tables, staining keys, culture differential criteria, virulence mechanisms, and antimicrobial resistance pathways are complete; genuine licensed Gram-stain, acid-fast, fungal, and parasitology photomicrographs are NOT yet bundled.',
  missingAssets: ['Licensed Gram-stain, acid-fast stain, KOH fungal, and stool ova/parasite reference photomicrographs'],
};

function makeMicroChapter(
  num: number,
  id: string,
  chapterTitle: string,
  title: string,
  taxonomicKey: string,
  summary: string,
  readingKey: keyof typeof VERIFIED_SOURCES,
  comp: { colA: string; colB: string; rows: ChapterAuthorSpec['comparisonTable']['rows'] },
  mechanisms: string[],
  clinical: string,
  fmas: string[],
  sys: ChapterAuthorSpec['relatedSystems'],
  mcqs: ChapterAuthorSpec['selfChecks'],
): ChapterAuthorSpec {
  return {
    id,
    domainId: 'microbiology_parasitology',
    chapterCode: `H${num}`,
    chapterOrder: num,
    chapterTitle,
    title,
    summary,
    targetTracks: ['school_foundations', 'secondary_premed', 'medical_foundations', 'allied_health', 'graduate_research'],
    curriculumMappings: [
      { frameworkId: 'pk_ncp_gs_4_8', gradeOrYear: 'Grades 6–8', unitOrModule: `Microorganisms & Disease (${chapterTitle})`, status: 'compulsory' },
      { frameworkId: 'pk_ncp_bio_9_12', gradeOrYear: 'Grade XI', unitOrModule: `Prokaryotes, Fungi & Acellular Life (${chapterTitle})`, status: 'elective' },
      { frameworkId: 'pk_pmdc_mbbs', gradeOrYear: 'MBBS Year 3', unitOrModule: `Medical Microbiology & Parasitology (${chapterTitle})`, status: 'compulsory' },
      { frameworkId: 'qaa_biosciences', gradeOrYear: 'BS Hons / MPhil', unitOrModule: `Microbial Pathogenesis & Antimicrobial Resistance (${chapterTitle})`, status: 'recommended' },
    ],
    prerequisites: ['Prokaryotic vs eukaryotic ultrastructure (B1)', 'Innate barrier defences'],
    learningObjectives: [
      `Classify key organisms in ${chapterTitle.toLowerCase()} by structural morphology, staining/genome rules, and transmission route.`,
      `Explain virulence toxins, replication strategies, or immune evasion mechanisms characteristic of ${chapterTitle.toLowerCase()}.`,
      `Interpret diagnostic microbiology culture/PCR/serology workups and infection-control measures honestly.`,
    ],
    depthExplanations: {
      school_foundations: `${summary} Microbes differ widely in shape, size, and how they spread—washing hands, safe water, sterilisation, and proper antimicrobial use prevent infectious illness.`,
      secondary_premed: `${taxonomicKey}. ${summary} Distinguishing Gram-positive, Gram-negative, viral, fungal, and parasitic biology guides clean diagnosis and antimicrobial targeting.`,
      medical_foundations: `${taxonomicKey}. ${mechanisms.join(' ')} Clinical diagnostic pearl: ${clinical}`,
      allied_health: `Infection prevention, safe specimen collection (pre-antibiotic blood cultures, CSF transport, sterile technique), and standard contact/droplet/airborne precautions directly prevent healthcare-associated transmission.`,
      graduate_research: `Comparative genomics, horizontal mobilome transfer (plasmids/transposons/SCCmec), type III/IV secretion effectors, and phenotypic AST MIC breakpoints drive mechanistic research across ${chapterTitle.toLowerCase()}.`,
    },
    keyConcepts: [
      { term: 'Morphology / Classification Key', definition: taxonomicKey },
      { term: 'Pathogenesis / Lab Basis', definition: mechanisms[0] ?? summary },
      { term: 'Clinical & Public Health Link', definition: clinical },
    ],
    keyFacts: [
      `Diagnostic Key: ${taxonomicKey}.`,
      'Local Gram/AFB/parasite microscopy photographs are honestly flagged Asset Required; never treat diagrams as clinical smears.',
    ],
    mechanisms,
    comparisonTable: { columnA: comp.colA, columnB: comp.colB, rows: comp.rows },
    misconceptions: [
      { misconception: 'Antibiotics cure acute viral upper-respiratory infections and speed flu recovery.', correction: 'Antibacterials target bacterial peptidoglycan, 70S ribosomes, or DNA gyrase—none of which exist in viruses; misuse accelerates MDR selection.' },
      { misconception: 'Alcohol hand rubs kill bacterial spores like Clostridioides difficile equally well as enveloped viruses.', correction: 'C. difficile endospores resist 70% alcohol; mechanical soap-and-water handwashing plus sporicidal hypochlorite environmental cleaning is required.' },
    ],
    clinicalCorrelation: clinical,
    summaryParagraph: `${chapterTitle} pairs pathogen structural biology (${taxonomicKey}) with diagnostic workflows, pathogenesis, and antimicrobial/infection-control principles.`,
    keyTakeaways: [
      taxonomicKey,
      mechanisms[0] ?? summary,
      clinical,
    ],
    crossSubjectLinks: [
      { domainId: 'immunology', relation: 'Toll-like receptors, antibodies, complement MAC, and CD4/CD8 T cells target specific microbial classes.' },
      { domainId: 'pharmacology', relation: 'Antimicrobial selective toxicity exploits structural/enzymatic divergences between pathogen and host.' },
    ],
    relatedSystems: sys,
    relatedFmaConceptIds: fmas,
    visualFormats: ['2d_diagram', 'microscopy', 'structured_text'],
    diagram: {
      id: `diag-h${num}`,
      title: `${chapterTitle} — Organism Diagnostic & Pathogenesis Key`,
      kind: 'comparison',
      caption: taxonomicKey,
      disclaimer: 'Conceptual diagnostic tree — licensed clinical Gram/AFB/parasite smears are marked Asset Required.',
      nodes: [
        { id: 'n1', label: 'Primary Morphotype / Genome', sublabel: taxonomicKey.slice(0, 62), tone: 'amber' },
        { id: 'n2', label: 'Virulence / Lab Criterion', sublabel: mechanisms[0]?.slice(0, 62) || summary.slice(0, 62), tone: 'blue' },
        { id: 'n3', label: 'Clinical / Stewardship Link', sublabel: clinical.slice(0, 62), tone: 'teal' },
      ],
      links: [
        { from: 'n1', to: 'n2', label: 'Differential stain / culture / NAAT screen' },
        { from: 'n2', to: 'n3', label: 'Targeted antimicrobial & precaution match' },
      ],
    },
    assetDisclosure: MICRO_GAP,
    activity: {
      title: `Microbiology Identification Unknowns Exercise (${chapterTitle})`,
      kind: 'interpretation',
      prompt: `Given the laboratory key (${taxonomicKey}), deduce the most likely pathogen class, explain its core virulence or metabolic hallmark, and pick appropriate biosafety/control measures.`,
      keyTakeaway: clinical,
    },
    readingKeys: [readingKey],
    shortAnswers: [
      { id: `sa-h${num}-1`, prompt: `Summarize the laboratory identification key (${taxonomicKey}) for ${chapterTitle}.`, expectedPoints: mechanisms.slice(0, 2), modelAnswer: `${taxonomicKey}. ${mechanisms.join(' ')}`, level: 'medical_foundations' },
      { id: `sa-h${num}-2`, prompt: `Contrast ${comp.colA} versus ${comp.colB}.`, expectedPoints: comp.rows.map((r) => `${r.dimension}: ${r.primary} vs ${r.comparator}`), modelAnswer: comp.rows.map((r) => `${r.dimension}: ${r.primary} vs ${r.comparator} (${r.clinicalOrFunctionalNote}).`).join(' '), level: 'secondary_premed' },
      { id: `sa-h${num}-3`, prompt: `Explain how pathogen biology in ${chapterTitle.toLowerCase()} guides diagnosis or infection prevention.`, expectedPoints: [clinical], modelAnswer: clinical, level: 'medical_foundations' },
    ],
    appliedCase: {
      id: `app-h${num}-1`,
      title: `Laboratory Identification & Containment Case: ${chapterTitle}`,
      scenario: `A teaching microbiology lab receives a specimen matching the diagnostic key for ${chapterTitle} (${taxonomicKey}).`,
      questions: ['Which structural feature governs its stain or culture behavior?', 'Which precaution or resistance pitfall matters most clinically?'],
      workedSolution: `${mechanisms[0]} Outcome: ${clinical}`,
      level: 'medical_foundations',
    },
    selfChecks: mcqs,
    educationalDisclaimer:
      'Educational microbiology principles only. Never use platform exercises to diagnose infections or select patient antimicrobial therapy.',
  };
}

